  assert.equal(daysBetween('2024-01-15', '2024-01-16'), 1);
  assert.equal(daysBetween('2024-01-15', '2024-01-25'), 10);
  assert.equal(daysBetween('2024-01-01', '2024-01-31'), 30);
});

test('daysBetween backward in time', () => {
  assert.equal(daysBetween('2024-01-16', '2024-01-15'), -1);
  assert.equal(daysBetween('2024-01-25', '2024-01-15'), -10);
});

test('daysBetween across month boundary', () => {
  assert.equal(daysBetween('2024-01-31', '2024-02-01'), 1);
  assert.equal(daysBetween('2024-01-31', '2024-02-29'), 29);
});

test('daysBetween across year boundary', () => {
  assert.equal(daysBetween('2024-12-31', '2025-01-01'), 1);
  assert.equal(daysBetween('2024-12-25', '2025-01-04'), 10);
});

test('daysBetween whole days only', () => {
  assert.equal(daysBetween('2024-01-15', '2024-01-15'), 0);
  assert.equal(daysBetween('2024-01-15', '2024-01-16'), 1);
  assert.equal(daysBetween('2024-01-15', '2024-01-17'), 2);
});

test('daysBetween symmetry (b-a = -(a-b))', () => {
  const a = '2024-01-15';
  const b = '2024-02-15';
  assert.equal(daysBetween(a, b), -daysBetween(b, a));
});

